#!/usr/bin/env python3
"""verify-conventions.py - single entry point that verifies ALL arjuy* conventions. Generated by arjuy-scaffold.

Runs, in order, and exits 1 if anything is found:
  V1  check-conventions.py          one top-level type per file, file name = type, namespace = folder
  V2  check-english-identifiers.py  identifiers in English (Spanish-word detector, allowlist)
  V3  Models live in a folder per entity:  Business/Models/<PluralEntity>/XRequestModel.cs
      (never directly in Models/, and the folder never equals the entity name: namespace/type clash)
  V4  One mapper per entity:  <Entity>Mapper.cs (Mapperly) or <Entity>Profile.cs (AutoMapper)
  V5  Services of an entity inherit BaseService<,>
  V6  Repositories of an entity inherit BaseRepository<>
  V8  (WARNING, non-blocking) comments written in English: comments must be in Spanish
  V7  Infrastructure types unknown to the MCP template (Base/ or Common/ folders, *Base, *Clock, *Helper...)
      are listed as DEVIATIONS; a deviation passes only when the type name is registered in SLICES.md
      under the heading "Desvios de la skill/MCP".

Usage: python3 scripts/verify-conventions.py [--allow a,b] [path]    (default: current directory)
"""
import importlib.util
import os
import re
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
KNOWN_INFRA = {
    "Entity", "ArgentinaTime", "MResult", "ErrorType", "IBaseRepository", "BaseRepository",
    "IBaseService", "BaseService", "AppDbContext", "ApiControllerBase", "DependencyInjectionConfig",
}
SUSPICIOUS_SUFFIX = re.compile(r"(Base|Clock|Helper|Helpers|Util|Utils|Utility|Manager)$")
IGNORED_DIRS = {"bin", "obj", ".git", "node_modules", "migrations", ".vs", "scripts", "tests"}


def load(name):
    path = os.path.join(HERE, name)
    spec = importlib.util.spec_from_file_location(name.replace("-", "_").replace(".py", ""), path)
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def cs_files(root):
    for current, dirs, files in os.walk(root):
        dirs[:] = [d for d in dirs if d.lower() not in IGNORED_DIRS]
        for file_name in sorted(files):
            lower = file_name.lower()
            if lower.endswith(".cs") and not lower.endswith((".g.cs", ".designer.cs", ".generated.cs")):
                yield os.path.join(current, file_name)


def declared(text):
    """[(kind, name, base_list_text)] for top-level-ish type declarations (comments/strings stripped)."""
    clean = CHECK.strip_noise(text)
    found = []
    for match in re.finditer(r"\b(class|interface|enum|struct|record)\s+([A-Za-z_]\w*)\s*(<[^>{]*>)?\s*(\([^)]*\))?\s*(:\s*[^{;]*)?", clean):
        found.append((match.group(1), match.group(2), match.group(5) or "", clean[: match.start()].count("\n") + 1,
                      "abstract" in clean[max(0, match.start() - 40): match.start()]))
    return found


def registered_deviations(root):
    probe = os.path.abspath(root)
    for _ in range(4):
        candidate = os.path.join(probe, "SLICES.md")
        if os.path.exists(candidate):
            with open(candidate, encoding="utf-8") as handle:
                text = handle.read()
            match = re.search(r"(?im)^#+[^\n]*desv[ií]os de la skill/mcp[^\n]*\n(.*?)(?=^#|\Z)", text, re.S)
            return match.group(1) if match else ""
        probe = os.path.dirname(probe)
    return ""


def main(argv):
    args = argv[1:]
    passthrough = []
    if "--allow" in args:
        index = args.index("--allow")
        passthrough = ["--allow", args[index + 1]]
        del args[index:index + 2]
    root = args[0] if args else "."
    findings = []
    warnings = []

    # V1 + V2 (reuse the two dedicated scripts so the rules live in one place)
    english = load("check-english-identifiers.py")
    allow = english.load_allowlist([w for w in (passthrough[1].split(",") if passthrough else []) if w])
    solution_allowlist = os.path.join(root, "scripts", "english-allowlist.txt")
    if os.path.exists(solution_allowlist):
        with open(solution_allowlist, encoding="utf-8") as handle:
            for raw in handle:
                entry = raw.split("#", 1)[0].strip().lower()
                if entry:
                    allow.add(entry)
    files = list(cs_files(root))
    for path in files:
        for error in CHECK.check_file(path):
            findings.append(("V1", "%s: %s" % (os.path.relpath(path), error)))
        for line, hits in english.english_comment_warnings(path):
            warnings.append("WARN [V8] %s:%d: comentario en inglés (los comentarios van en español): %s" % (os.path.relpath(path), line, hits))
        for line, identifier, reason in english.check_file(path, allow):
            findings.append(("V2", "%s:%d:%s (%s)" % (os.path.relpath(path), line, identifier, reason)))

    entities, parsed = set(), []
    for path in files:
        with open(path, encoding="utf-8-sig", errors="replace") as handle:
            text = handle.read()
        declarations = declared(text)
        parsed.append((path, declarations))
        if "/entities/" in path.replace(os.sep, "/").lower():
            entities.update(name for kind, name, *_ in declarations if kind == "class")

    deviations_text = registered_deviations(root)
    for path, declarations in parsed:
        norm = path.replace(os.sep, "/")
        rel = os.path.relpath(path)
        for kind, name, bases, line, abstract in declarations:
            # V3 models in entity folders
            if name.endswith(("RequestModel", "ResponseModel")):
                match = re.search(r"/Models/(.+)/[^/]+\.cs$", norm)
                if not match:
                    findings.append(("V3", "%s:%d:%s must live in Models/<PluralEntity>/ (a folder per entity; Models/Common for shared)" % (rel, line, name)))
                else:
                    entity = re.sub(r"(Request|Response)Model$", "", name)
                    if match.group(1) == entity:
                        findings.append(("V3", "%s:%d:%s folder '%s' equals the entity name; use the plural to avoid namespace/type clash" % (rel, line, name, entity)))
            # V4 mapper per entity
            if re.search(r"/(Mappers|Mappings)/", norm) and kind == "class":
                entity = re.sub(r"(Mapper|Profile)$", "", name)
                if not name.endswith(("Mapper", "Profile")) or (entities and entity not in entities):
                    findings.append(("V4", "%s:%d:%s must be '<Entity>Mapper' (Mapperly) or '<Entity>Profile' (AutoMapper), one per entity" % (rel, line, name)))
            # V5 / V6 inheritance
            if kind == "class" and not abstract and "/Base/" not in norm:
                if name.endswith("Service") and name[:-len("Service")] in entities and "BaseService" not in bases:
                    findings.append(("V5", "%s:%d:%s must inherit BaseService<TEntity, TResponseModel>" % (rel, line, name)))
                if name.endswith("Repository") and name[:-len("Repository")] in entities and "BaseRepository" not in bases:
                    findings.append(("V6", "%s:%d:%s must inherit BaseRepository<TEntity>" % (rel, line, name)))
            # V7 unknown infrastructure
            in_infra_folder = bool(re.search(r"/(Base|Common)/", norm)) and "/Models/" not in norm
            if kind in ("class", "interface") and name not in KNOWN_INFRA and (in_infra_folder or SUSPICIOUS_SUFFIX.search(name.lstrip("I") if kind == "interface" else name)):
                if name not in deviations_text:
                    findings.append(("V7", "%s:%d:%s is infrastructure unknown to the MCP template: use the MCP type or register it in SLICES.md under 'Desvios de la skill/MCP' (what, why, alternative)" % (rel, line, name)))

    for code, message in findings:
        print("[%s] %s" % (code, message))
    for warning in warnings:
        print(warning)
    print("verify-conventions: %d files checked, %d findings, %d warnings (V8, non-blocking)" % (len(files), len(findings), len(warnings)))
    return 1 if findings else 0


CHECK = load("check-conventions.py")

if __name__ == "__main__":
    sys.exit(main(sys.argv))
